function formatVowelForTTS(vowelChar, seriesType) {
	if (!vowelChar || !vowelChar.trim()) return "";
	if (seriesType?.trim().toUpperCase() === "O") return `\u17A2\u17CA${vowelChar}`;
	return `\u17A2${vowelChar}`;
}
